"""Exercices historiques du chapitre 10 (identifiants conservés), extraits
de exercises_bank_premiere.json le 2026-10-26 : (id, notion, niveau, énoncé,
réponse, indice, étapes). Réécrits par banque_ch10.py."""

HISTORIQUES = (
    (1884, 'Variables aléatoires réelles', 1, 'Une variable aléatoire $X$ peut prendre les valeurs $-4$, $0$, $5$ et $7$. On donne $P(X=-4) = \\dfrac{1}{5}$, $P(X=0) = \\dfrac{1}{5}$, $P(X=5) = \\dfrac{1}{10}$. Déterminer $P(X=7)$.', '$P(X=7) = \\dfrac{1}{2}$', "La somme de toutes les probabilités d'une variable aléatoire vaut toujours $1$.", ("Étape 1 : La somme des probabilités d'une loi de probabilité vaut $1$.", 'Étape 2 : $P(X=7) = 1 - \\left(\\dfrac{1}{5} + \\dfrac{1}{5} + \\dfrac{1}{10}\\right) = \\dfrac{1}{2}$.')),
    (1889, 'Variables aléatoires réelles', 1, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-5)=\\dfrac{1}{25}$, $P(X=0)=\\dfrac{1}{4}$, $P(X=4)=\\dfrac{9}{100}$, $P(X=6)=\\dfrac{31}{50}$. Calculer $P(X \\leqslant 0)$.", '$P(X \\leqslant 0) = \\dfrac{29}{100}$', 'Additionner les probabilités de toutes les valeurs concernées.', ('Étape 1 : $P(X\\leqslant 0)$ est la somme des probabilités pour toutes les valeurs de $X$ inférieures ou égales à $0$.', 'Étape 2 : $P(X\\leqslant 0) = \\dfrac{1}{25} + \\dfrac{1}{4} = \\dfrac{29}{100}$.')),
    (1942, 'Espérance – Variance – Écart-type', 1, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-1)=\\dfrac{3}{5}$, $P(X=3)=\\dfrac{1}{5}$, $P(X=6)=\\dfrac{1}{5}$. Calculer $V(X)$ puis $\\sigma(X)$.", '$V(X) = \\dfrac{204}{25}$ et $\\sigma(X) = \\sqrt{\\dfrac{204}{25}}$', 'Utiliser $V(X)=E(X^2)-(E(X))^2$ puis $\\sigma(X)=\\sqrt{V(X)}$.', ("Étape 1 : On calcule d'abord $E(X) = \\dfrac{6}{5}$.", 'Étape 2 : $E(X^2) = -1^2\\times\\dfrac{3}{5} + 3^2\\times\\dfrac{1}{5} + 6^2\\times\\dfrac{1}{5} = \\dfrac{48}{5}$.', 'Étape 3 : $V(X) = E(X^2) - (E(X))^2 = \\dfrac{48}{5} - (\\dfrac{6}{5})^2 = \\dfrac{204}{25}$.', 'Étape 4 : $\\sigma(X) = \\sqrt{V(X)} = \\sqrt{\\dfrac{204}{25}}$.')),
    (1944, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ est telle que $E(X) = \\dfrac{1}{2}$ et $V(X) = \\dfrac{123}{4}$. On pose $Y = 2X -3$. Calculer $E(Y)$ et $V(Y)$.', '$E(Y) = -2$ et $V(Y) = 123$', 'Utiliser les formules de linéarité $E(aX+b)=aE(X)+b$ et $V(aX+b)=a^2V(X)$.', ('Étape 1 : On utilise $E(aX+b) = aE(X)+b$ : $E(Y) = 2\\times\\dfrac{1}{2} -3 = -2$.', 'Étape 2 : On utilise $V(aX+b) = a^2V(X)$ : $V(Y) = 2^2 \\times \\dfrac{123}{4} = 123$.')),
    (1945, 'Espérance – Variance – Écart-type', 1, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-4)=\\dfrac{2}{5}$, $P(X=-3)=\\dfrac{1}{2}$, $P(X=3)=\\dfrac{1}{10}$. Calculer l'espérance $E(X)$.", '$E(X) = -\\dfrac{14}{5}$', 'Utiliser $E(X)=\\sum x_ip_i$.', ('Étape 1 : On utilise $E(X) = \\displaystyle\\sum_i x_i \\, p_i$.', 'Étape 2 : $E(X) = -4\\times\\dfrac{2}{5} + -3\\times\\dfrac{1}{2} + 3\\times\\dfrac{1}{10} = -\\dfrac{14}{5}$.')),
    (1946, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ est telle que $E(X) = -\\dfrac{6}{5}$ et $V(X) = \\dfrac{279}{25}$. On pose $Y = 3X +0$. Calculer $E(Y)$ et $V(Y)$.', '$E(Y) = -\\dfrac{18}{5}$ et $V(Y) = \\dfrac{2511}{25}$', 'Utiliser les formules de linéarité $E(aX+b)=aE(X)+b$ et $V(aX+b)=a^2V(X)$.', ('Étape 1 : On utilise $E(aX+b) = aE(X)+b$ : $E(Y) = 3\\times-\\dfrac{6}{5} +0 = -\\dfrac{18}{5}$.', 'Étape 2 : On utilise $V(aX+b) = a^2V(X)$ : $V(Y) = 3^2 \\times \\dfrac{279}{25} = \\dfrac{2511}{25}$.')),
    (1947, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ est telle que $E(X) = \\dfrac{3}{5}$ et $V(X) = \\dfrac{76}{25}$. On pose $Y = 2X +0$. Calculer $E(Y)$ et $V(Y)$.', '$E(Y) = \\dfrac{6}{5}$ et $V(Y) = \\dfrac{304}{25}$', 'Utiliser les formules de linéarité $E(aX+b)=aE(X)+b$ et $V(aX+b)=a^2V(X)$.', ('Étape 1 : On utilise $E(aX+b) = aE(X)+b$ : $E(Y) = 2\\times\\dfrac{3}{5} +0 = \\dfrac{6}{5}$.', 'Étape 2 : On utilise $V(aX+b) = a^2V(X)$ : $V(Y) = 2^2 \\times \\dfrac{76}{25} = \\dfrac{304}{25}$.')),
    (1949, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ est telle que $E(X) = -\\dfrac{41}{20}$ et $V(X) = \\dfrac{4059}{400}$. On pose $Y = 2X -4$. Calculer $E(Y)$ et $V(Y)$.', '$E(Y) = -\\dfrac{81}{10}$ et $V(Y) = \\dfrac{4059}{100}$', 'Utiliser les formules de linéarité $E(aX+b)=aE(X)+b$ et $V(aX+b)=a^2V(X)$.', ('Étape 1 : On utilise $E(aX+b) = aE(X)+b$ : $E(Y) = 2\\times-\\dfrac{41}{20} -4 = -\\dfrac{81}{10}$.', 'Étape 2 : On utilise $V(aX+b) = a^2V(X)$ : $V(Y) = 2^2 \\times \\dfrac{4059}{400} = \\dfrac{4059}{100}$.')),
    (1966, 'Espérance – Variance – Écart-type', 3, 'Une variable aléatoire $X$ est telle que $E(X) = -3$ et $V(X) = 2$. On pose $Y = 1X +4$. Calculer $E(Y)$ et $V(Y)$.', '$E(Y) = 1$ et $V(Y) = 2$', 'Utiliser les formules de linéarité $E(aX+b)=aE(X)+b$ et $V(aX+b)=a^2V(X)$.', ('Étape 1 : On utilise $E(aX+b) = aE(X)+b$ : $E(Y) = 1\\times-3 +4 = 1$.', 'Étape 2 : On utilise $V(aX+b) = a^2V(X)$ : $V(Y) = 1^2 \\times 2 = 2$.')),
    (2056, 'Variables aléatoires réelles', 1, 'Une variable aléatoire $X$ peut prendre les valeurs $-3$, $-1$, $2$, $4$ et $6$. On donne $P(X=-3)=\\dfrac{1}{10}$, $P(X=-1)=\\dfrac{1}{5}$, $P(X=2)=\\dfrac{3}{10}$, $P(X=4)=\\dfrac{1}{5}$. Déterminer $P(X=6)$.', '$P(X=6) = \\dfrac{1}{5}$', "La somme de toutes les probabilités d'une variable aléatoire vaut toujours $1$.", ("Étape 1 : La somme des probabilités d'une loi de probabilité vaut $1$.", 'Étape 2 : $P(X=6) = 1 - \\left(\\dfrac{1}{10}+\\dfrac{1}{5}+\\dfrac{3}{10}+\\dfrac{1}{5}\\right) = \\dfrac{1}{5}$.')),
    (2057, 'Variables aléatoires réelles', 1, 'Une variable aléatoire $X$ peut prendre les valeurs $0$, $2$, $5$, $8$ et $9$. On donne $P(X=0)=\\dfrac{3}{20}$, $P(X=2)=\\dfrac{1}{4}$, $P(X=5)=\\dfrac{3}{10}$, $P(X=8)=\\dfrac{1}{10}$. Déterminer $P(X=9)$.', '$P(X=9) = \\dfrac{1}{5}$', "La somme de toutes les probabilités d'une variable aléatoire vaut toujours $1$.", ("Étape 1 : La somme des probabilités d'une loi de probabilité vaut $1$.", 'Étape 2 : $P(X=9) = 1 - \\left(\\dfrac{3}{20}+\\dfrac{1}{4}+\\dfrac{3}{10}+\\dfrac{1}{10}\\right) = \\dfrac{1}{5}$.')),
    (2058, 'Variables aléatoires réelles', 3, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-4)=\\dfrac{1}{10}$, $P(X=-1)=\\dfrac{1}{5}$, $P(X=0)=\\dfrac{3}{20}$, $P(X=3)=\\dfrac{1}{4}$, $P(X=5)=\\dfrac{3}{10}$. Calculer $P(-1 \\leqslant X \\leqslant 3)$.", '$P(-1 \\leqslant X \\leqslant 3) = \\dfrac{3}{5}$', 'Identifier toutes les valeurs de $X$ comprises entre $-1$ et $3$ inclus, puis additionner leurs probabilités.', ('Étape 1 : Les valeurs de $X$ comprises entre $-1$ et $3$ (inclus) sont $-1$, $0$ et $3$.', 'Étape 2 : $P(-1\\leqslant X\\leqslant 3) = P(X=-1)+P(X=0)+P(X=3) = \\dfrac{1}{5}+\\dfrac{3}{20}+\\dfrac{1}{4} = \\dfrac{3}{5}$.')),
    (2059, 'Variables aléatoires réelles', 3, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-2)=\\dfrac{1}{20}$, $P(X=1)=\\dfrac{3}{20}$, $P(X=3)=\\dfrac{1}{4}$, $P(X=6)=\\dfrac{1}{5}$, $P(X=9)=\\dfrac{7}{20}$. Calculer $P(X \\geqslant 3)$.", '$P(X \\geqslant 3) = \\dfrac{4}{5}$', 'Additionner les probabilités de toutes les valeurs supérieures ou égales à $3$.', ('Étape 1 : Les valeurs de $X$ supérieures ou égales à $3$ sont $3$, $6$ et $9$.', 'Étape 2 : $P(X\\geqslant 3) = P(X=3)+P(X=6)+P(X=9) = \\dfrac{1}{4}+\\dfrac{1}{5}+\\dfrac{7}{20} = \\dfrac{4}{5}$.')),
    (2060, 'Variables aléatoires réelles', 2, 'On lance un dé équilibré à $6$ faces. Si le résultat est $6$, le joueur gagne $10$ euros ; sinon, il ne gagne rien. On note $X$ le gain du joueur. La loi de $X$ est $P(X=10)=\\dfrac{1}{6}$ et $P(X=0)=\\dfrac{5}{6}$. Interpréter la valeur $P(X=0) = \\dfrac{5}{6}$ dans le contexte du jeu.', "Sur un grand nombre de parties, le joueur ne gagne rien environ $5$ fois sur $6$, c'est-à-dire dans $\\dfrac{5}{6}\\approx 83,3\\%$ des parties.", '$P(X=0)$ est la proportion de parties, sur un grand nombre de répétitions, où le gain est nul.', ("Étape 1 : $P(X=0) = \\dfrac{5}{6}$ signifie que l'événement « le joueur ne gagne rien » (c'est-à-dire ne pas obtenir de $6$) a une probabilité de $\\dfrac{5}{6}$.", "Étape 2 : Concrètement, si un grand nombre de joueurs jouent une partie, environ $83,3\\%$ d'entre eux repartiront sans gain, ce qui est cohérent avec le fait qu'un seul résultat sur $6$ (le $6$) fait gagner.")),
    (2061, 'Variables aléatoires réelles', 2, "Dans un lot de pièces, on note $X$ le nombre de défauts détectés sur une pièce prélevée au hasard. Sa loi de probabilité est $P(X=0)=\\dfrac{7}{10}$, $P(X=1)=\\dfrac{1}{5}$, $P(X=2)=\\dfrac{1}{20}$, $P(X=3)=\\dfrac{1}{20}$. Interpréter la probabilité $P(X \\geqslant 2)$ pour le service qualité, après l'avoir calculée.", '$P(X \\geqslant 2) = \\dfrac{1}{10}$ : environ $10\\%$ des pièces présentent au moins deux défauts.', 'Additionner les probabilités des valeurs de $X$ supérieures ou égales à $2$, puis traduire ce nombre en proportion de pièces concernées.', ('Étape 1 : $P(X\\geqslant 2) = P(X=2)+P(X=3) = \\dfrac{1}{20}+\\dfrac{1}{20} = \\dfrac{1}{10}$.', "Étape 2 : Cela signifie qu'environ $10\\%$ des pièces du lot présentent au moins deux défauts, ce qui peut justifier un contrôle renforcé si ce seuil est jugé trop élevé par le service qualité.")),
    (2062, 'Variables aléatoires réelles', 3, 'On lance un dé équilibré à $6$ faces. Si le résultat est pair, le joueur gagne une somme en euros égale au résultat du dé ; si le résultat est impair, il perd $3$ euros. On note $X$ le gain algébrique du joueur (positif si gain, négatif si perte). Déterminer la loi de probabilité de $X$.', '$P(X=-3)=\\dfrac{1}{2}$, $P(X=2)=\\dfrac{1}{6}$, $P(X=4)=\\dfrac{1}{6}$, $P(X=6)=\\dfrac{1}{6}$', "Repérer d'abord les valeurs possibles de $X$ selon les résultats du dé, puis regrouper les issues qui donnent la même valeur de $X$.", ('Étape 1 : Les résultats impairs ($1$, $3$, $5$) donnent tous $X=-3$ (perte de $3$ euros) : il y a $3$ issues favorables sur $6$.', 'Étape 2 : Les résultats pairs donnent respectivement $X=2$ (pour un $2$), $X=4$ (pour un $4$) et $X=6$ (pour un $6$) : chacun correspond à $1$ issue sur $6$.', 'Étape 3 : On obtient $P(X=-3)=\\dfrac{3}{6}=\\dfrac{1}{2}$, $P(X=2)=P(X=4)=P(X=6)=\\dfrac{1}{6}$.')),
    (2063, 'Variables aléatoires réelles', 3, 'Une loterie vend $100$ billets à $2$ euros chacun. Un billet permet de gagner $50$ euros (il y en a $1$), $10$ euros (il y en a $4$), ou rien (les $95$ autres billets). On note $X$ le gain net du joueur (somme gagnée moins le prix du billet). Déterminer la loi de probabilité de $X$.', '$P(X=48)=\\dfrac{1}{100}$, $P(X=8)=\\dfrac{4}{100}=\\dfrac{1}{25}$, $P(X=-2)=\\dfrac{95}{100}=\\dfrac{19}{20}$', 'Le gain net est la somme gagnée diminuée des $2$ euros du billet, y compris pour les billets perdants.', ('Étape 1 : Pour le billet gagnant $50$ euros, le gain net est $50-2=48$ euros ; il y a $1$ billet sur $100$ dans ce cas.', 'Étape 2 : Pour les billets gagnant $10$ euros, le gain net est $10-2=8$ euros ; il y en a $4$ sur $100$.', 'Étape 3 : Pour les billets perdants, le gain net est $0-2=-2$ euros ; il y en a $95$ sur $100$.', 'Étape 4 : $P(X=48)=\\dfrac{1}{100}$, $P(X=8)=\\dfrac{4}{100}=\\dfrac{1}{25}$, $P(X=-2)=\\dfrac{95}{100}=\\dfrac{19}{20}$. On vérifie que la somme vaut bien $1$.')),
    (2064, 'Variables aléatoires réelles', 1, 'On propose la loi de probabilité suivante pour une variable aléatoire $X$ : $P(X=-1)=\\dfrac{1}{4}$, $P(X=0)=\\dfrac{1}{2}$, $P(X=2)=\\dfrac{1}{2}$. Vrai ou faux : « ceci est une loi de probabilité valide ». Justifier.', 'Faux : la somme des probabilités vaut $\\dfrac{5}{4} \\neq 1$.', 'Vérifier que la somme des probabilités proposées vaut exactement $1$.', ('Étape 1 : Une loi de probabilité doit vérifier que la somme de toutes les probabilités vaut $1$.', 'Étape 2 : $\\dfrac{1}{4}+\\dfrac{1}{2}+\\dfrac{1}{2} = \\dfrac{1}{4}+\\dfrac{2}{4}+\\dfrac{2}{4} = \\dfrac{5}{4} \\neq 1$.', "Étape 3 : La somme dépasse $1$ : ce n'est donc pas une loi de probabilité valide. L'affirmation est fausse.")),
    (2065, 'Variables aléatoires réelles', 2, 'Un élève propose la loi $P(X=-2)=\\dfrac{3}{4}$, $P(X=1)=\\dfrac{1}{2}$, $P(X=3)=-\\dfrac{1}{4}$ pour une variable aléatoire $X$, en justifiant que la somme vaut bien $1$. Vrai ou faux : « cette proposition est acceptable ». Justifier.', 'Faux : une probabilité ne peut jamais être négative, même si la somme totale vaut $1$.', 'Une probabilité doit toujours être un nombre compris entre $0$ et $1$ ; vérifier chaque valeur, pas seulement la somme.', ("Étape 1 : On vérifie d'abord la somme : $\\dfrac{3}{4}+\\dfrac{1}{2}-\\dfrac{1}{4} = 1$, la somme vaut bien $1$.", 'Étape 2 : Cependant, une loi de probabilité exige que chaque probabilité $P(X=x_i)$ soit comprise entre $0$ et $1$. Or $P(X=3) = -\\dfrac{1}{4} < 0$, ce qui est impossible.', "Étape 3 : La proposition n'est donc pas acceptable, même si la somme est correcte : l'affirmation est fausse.")),
    (2066, 'Variables aléatoires réelles', 2, 'Une variable aléatoire $X$ prend les valeurs $-2$, $0$, $3$ et $5$, avec $P(X=-2)=\\dfrac{1}{5}$, $P(X=0)=\\dfrac{3}{10}$, $P(X=3)=\\dfrac{1}{5}$. Un élève calcule $P(X=5)$ ainsi : « $P(X=5) = 1 - P(X=-2) - P(X=0) = 1 - \\dfrac{1}{5} - \\dfrac{3}{10} = \\dfrac{1}{2}$ ». Identifier son erreur et donner la valeur correcte de $P(X=5)$.', "$P(X=5) = \\dfrac{3}{10}$ : l'élève a oublié de soustraire $P(X=3) = \\dfrac{1}{5}$ dans son calcul.", "Il faut soustraire les probabilités de TOUTES les autres valeurs possibles de $X$, pas seulement certaines d'entre elles.", ("Étape 1 : L'élève a oublié la valeur $P(X=3) = \\dfrac{1}{5}$ dans sa soustraction : il doit soustraire les probabilités des quatre autres valeurs, mais $X$ en prend quatre au total (dont $X=5$), donc il faut soustraire les trois probabilités connues.", 'Étape 2 : Le calcul correct est $P(X=5) = 1 - P(X=-2) - P(X=0) - P(X=3) = 1 - \\dfrac{1}{5} - \\dfrac{3}{10} - \\dfrac{1}{5}$.', 'Étape 3 : $\\dfrac{1}{5}+\\dfrac{3}{10}+\\dfrac{1}{5} = \\dfrac{2}{10}+\\dfrac{3}{10}+\\dfrac{2}{10} = \\dfrac{7}{10}$, donc $P(X=5) = 1-\\dfrac{7}{10} = \\dfrac{3}{10}$, différent du résultat erroné $\\dfrac{1}{2}$.')),
    (2067, 'Variables aléatoires réelles', 2, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-3)=\\dfrac{1}{10}$, $P(X=-1)=\\dfrac{1}{5}$, $P(X=2)=\\dfrac{2}{5}$, $P(X=5)=\\dfrac{3}{10}$. Pour calculer $P(X < 0)$, un élève écrit : « $P(X<0) = P(X=-3)+P(X=-1)+P(X=2) = \\dfrac{1}{10}+\\dfrac{1}{5}+\\dfrac{2}{5} = \\dfrac{7}{10}$ ». Identifier son erreur et donner le calcul correct.", "$P(X<0) = \\dfrac{3}{10}$ : l'élève a inclus à tort la valeur $X=2$, qui n'est pas strictement négative.", "$P(X<0)$ ne concerne que les valeurs strictement négatives de $X$ ; $2$ n'en fait pas partie.", ("Étape 1 : L'élève a inclus $P(X=2)$ dans son calcul de $P(X<0)$, alors que $2$ n'est pas une valeur strictement négative.", 'Étape 2 : Seules les valeurs $-3$ et $-1$ sont strictement négatives, donc $P(X<0) = P(X=-3)+P(X=-1) = \\dfrac{1}{10}+\\dfrac{1}{5} = \\dfrac{3}{10}$.', 'Étape 3 : Le résultat correct $\\dfrac{3}{10}$ est bien inférieur au résultat erroné $\\dfrac{7}{10}$.')),
    (2068, 'Variables aléatoires réelles', 2, "Une enquête auprès de familles donne la loi de probabilité du nombre d'enfants $X$ par foyer : $P(X=0)=\\dfrac{3}{10}$, $P(X=1)=\\dfrac{3}{10}$, $P(X=2)=\\dfrac{1}{4}$, $P(X=3)=\\dfrac{3}{20}$. Calculer la probabilité qu'un foyer choisi au hasard ait au moins un enfant.", '$P(X \\geqslant 1) = \\dfrac{7}{10}$', "Utiliser l'événement contraire : « au moins un enfant » est le contraire de « aucun enfant ».", ("Étape 1 : L'événement contraire de « $X \\geqslant 1$ » est « $X=0$ ».", 'Étape 2 : $P(X\\geqslant 1) = 1-P(X=0) = 1-\\dfrac{3}{10} = \\dfrac{7}{10}$.')),
    (2069, 'Variables aléatoires réelles', 2, "Un centre d'appels étudie le nombre $X$ d'appels manqués par employé et par jour : $P(X=0)=\\dfrac{2}{5}$, $P(X=1)=\\dfrac{3}{10}$, $P(X=2)=\\dfrac{3}{20}$, $P(X=3)=\\dfrac{1}{10}$, $P(X=4)=\\dfrac{1}{20}$. La direction considère qu'un employé a besoin d'un accompagnement s'il manque $2$ appels ou plus dans la journée. Calculer la probabilité qu'un employé pris au hasard soit dans ce cas.", '$P(X \\geqslant 2) = \\dfrac{3}{10}$', 'Additionner les probabilités des valeurs $2$, $3$ et $4$.', ('Étape 1 : $P(X\\geqslant 2) = P(X=2)+P(X=3)+P(X=4) = \\dfrac{3}{20}+\\dfrac{1}{10}+\\dfrac{1}{20} = \\dfrac{3}{10}$.', "Étape 2 : Environ $30\\%$ des employés manquent au moins $2$ appels par jour et pourraient donc bénéficier d'un accompagnement.")),
    (2070, 'Variables aléatoires réelles', 3, 'Deux jeux proposent chacun un gain $X$ (jeu $A$) ou $Y$ (jeu $B$). Jeu $A$ : $P(X=-2)=\\dfrac{1}{4}$, $P(X=0)=\\dfrac{1}{4}$, $P(X=3)=\\dfrac{1}{2}$. Jeu $B$ : $P(Y=-2)=\\dfrac{1}{10}$, $P(Y=0)=\\dfrac{2}{5}$, $P(Y=3)=\\dfrac{1}{2}$. Comparer $P(X\\leqslant 0)$ et $P(Y\\leqslant 0)$, puis indiquer quel jeu comporte le moins de risque de ne rien gagner ou de perdre.', '$P(X\\leqslant 0) = \\dfrac{1}{2}$ et $P(Y\\leqslant 0) = \\dfrac{1}{2}$ : ces probabilités sont égales, les deux jeux comportent le même risque de gain nul ou négatif.', 'Additionner les probabilités des valeurs négatives ou nulles pour chaque jeu, puis comparer.', ('Étape 1 : $P(X\\leqslant 0) = P(X=-2)+P(X=0) = \\dfrac{1}{4}+\\dfrac{1}{4} = \\dfrac{1}{2}$.', 'Étape 2 : $P(Y\\leqslant 0) = P(Y=-2)+P(Y=0) = \\dfrac{1}{10}+\\dfrac{2}{5} = \\dfrac{1}{2}$.', 'Étape 3 : Les deux probabilités valent $\\dfrac{1}{2}$ : les deux jeux présentent exactement le même risque de gain nul ou négatif, bien que leurs répartitions internes diffèrent.')),
    (2071, 'Variables aléatoires réelles', 4, 'Un jeu de fléchettes comporte $3$ zones : centre (probabilité de la toucher $\\dfrac{1}{10}$, gain $20$ euros), milieu (probabilité $\\dfrac{3}{10}$, gain $5$ euros), extérieur (probabilité $\\dfrac{6}{10}$, gain $-2$ euros, correspondant au coût du jeu). 1) Vérifier que ces probabilités définissent bien une loi de probabilité pour le gain $X$. 2) Calculer $P(X > 0)$. 3) Interpréter ce résultat pour un joueur.', "La somme des probabilités vaut $1$ (loi valide) ; $P(X>0) = \\dfrac{4}{10} = \\dfrac{2}{5}$ : le joueur gagne de l'argent dans $2$ parties sur $5$ en moyenne.", 'Vérifier la somme des probabilités, puis identifier les valeurs de $X$ strictement positives.', ("Étape 1 : $\\dfrac{1}{10}+\\dfrac{3}{10}+\\dfrac{6}{10} = \\dfrac{10}{10} = 1$ : il s'agit bien d'une loi de probabilité valide.", 'Étape 2 : Les valeurs de $X$ strictement positives sont $20$ (centre) et $5$ (milieu), donc $P(X>0) = \\dfrac{1}{10}+\\dfrac{3}{10} = \\dfrac{4}{10} = \\dfrac{2}{5}$.', 'Étape 3 : Un joueur a donc $2$ chances sur $5$ (soit $40\\%$) de repartir avec un gain positif, et $3$ chances sur $5$ de perdre les $2$ euros du jeu (zone extérieure).')),
    (2072, 'Variables aléatoires réelles', 4, "Dans un magasin, on interroge $200$ clients sur le nombre d'articles achetés lors de leur visite : $40$ clients n'ont rien acheté, $60$ ont acheté $1$ article, $70$ ont acheté $2$ articles, $30$ ont acheté $3$ articles. On note $X$ le nombre d'articles achetés par un client choisi au hasard. 1) Déterminer la loi de probabilité de $X$. 2) Calculer $P(X \\geqslant 2)$. 3) En déduire la proportion de clients ayant acheté au moins $2$ articles.", '$P(X=0)=\\dfrac{1}{5}$, $P(X=1)=\\dfrac{3}{10}$, $P(X=2)=\\dfrac{7}{20}$, $P(X=3)=\\dfrac{3}{20}$ ; $P(X\\geqslant 2) = \\dfrac{1}{2}$, soit 50\\% des clients.', "Diviser chaque effectif par l'effectif total pour obtenir la loi, puis additionner les probabilités voulues.", ("Étape 1 : L'effectif total est $40+60+70+30=200$.", 'Étape 2 : $P(X=0)=\\dfrac{40}{200}=\\dfrac{1}{5}$, $P(X=1)=\\dfrac{60}{200}=\\dfrac{3}{10}$, $P(X=2)=\\dfrac{70}{200}=\\dfrac{7}{20}$, $P(X=3)=\\dfrac{30}{200}=\\dfrac{3}{20}$.', 'Étape 3 : $P(X\\geqslant 2) = P(X=2)+P(X=3) = \\dfrac{7}{20}+\\dfrac{3}{20} = \\dfrac{1}{2}$.', "Étape 4 : Cela signifie que $50\\%$ des clients de l'échantillon ont acheté au moins $2$ articles lors de leur visite.")),
    (2073, 'Variables aléatoires réelles', 4, "Un questionnaire de satisfaction demande de noter un service de $1$ (très mauvais) à $6$ (excellent). La note $X$ obtenue suit la loi $P(X=1)=\\dfrac{1}{20}$, $P(X=2)=\\dfrac{1}{5}$, $P(X=3)=\\dfrac{2}{5}$, $P(X=4)=\\dfrac{1}{5}$, $P(X=5)=\\dfrac{1}{20}$, $P(X=6)=\\dfrac{1}{10}$. 1) Vérifier que cette loi est valide. 2) Déterminer la note la plus fréquemment attribuée. 3) Calculer la probabilité qu'un client attribue une note strictement supérieure à $4$, et interpréter.", 'La loi est valide (somme $=1$) ; la note la plus fréquente est $3$ (probabilité $\\dfrac{2}{5}$) ; $P(X>4) = \\dfrac{3}{20}$, soit $15\\%$ des clients qui attribuent une note de $5$ ou $6$.', 'Comparer toutes les probabilités pour trouver le maximum, puis additionner les probabilités de $X=5$ et $X=6$ pour $P(X>4)$.', ('Étape 1 : $\\dfrac{1}{20}+\\dfrac{1}{5}+\\dfrac{2}{5}+\\dfrac{1}{5}+\\dfrac{1}{20}+\\dfrac{1}{10} = \\dfrac{1}{20}+\\dfrac{4}{20}+\\dfrac{8}{20}+\\dfrac{4}{20}+\\dfrac{1}{20}+\\dfrac{2}{20} = \\dfrac{20}{20} = 1$ : la loi est valide.', 'Étape 2 : La plus grande probabilité est $P(X=3)=\\dfrac{2}{5}$ : la note $3$ est donc la plus fréquemment attribuée.', 'Étape 3 : $P(X>4) = P(X=5)+P(X=6) = \\dfrac{1}{20}+\\dfrac{1}{10} = \\dfrac{1}{20}+\\dfrac{2}{20} = \\dfrac{3}{20}$.', "Étape 4 : Seulement $15\\%$ des clients attribuent une note élevée ($5$ ou $6$) : le service est majoritairement jugé moyen (note $3$), ce qui peut inquiéter l'entreprise si elle visait l'excellence.")),
    (2074, 'Espérance – Variance – Écart-type', 1, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-2)=\\dfrac{1}{4}$, $P(X=1)=\\dfrac{1}{2}$, $P(X=4)=\\dfrac{1}{4}$. Calculer $E(X)$ puis $V(X)$.", '$E(X) = 1$ et $V(X) = \\dfrac{9}{2}$', "Calculer d'abord $E(X)$, puis $E(X^2)$, puis utiliser $V(X)=E(X^2)-(E(X))^2$.", ('Étape 1 : $E(X) = -2\\times\\dfrac{1}{4} + 1\\times\\dfrac{1}{2} + 4\\times\\dfrac{1}{4} = 1$.', 'Étape 2 : $E(X^2) = 4\\times\\dfrac{1}{4} + 1\\times\\dfrac{1}{2} + 16\\times\\dfrac{1}{4} = \\dfrac{11}{2}$.', 'Étape 3 : $V(X) = E(X^2) - (E(X))^2 = \\dfrac{11}{2} - (1)^2 = \\dfrac{9}{2}$.')),
    (2075, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ a pour variance $V(X) = \\dfrac{9}{4}$. Calculer son écart-type $\\sigma(X)$.', '$\\sigma(X) = \\dfrac{3}{2}$', 'Utiliser $\\sigma(X) = \\sqrt{V(X)}$ et simplifier la racine si possible.', ('Étape 1 : $\\sigma(X) = \\sqrt{V(X)} = \\sqrt{\\dfrac{9}{4}}$.', 'Étape 2 : $\\sqrt{\\dfrac{9}{4}} = \\dfrac{\\sqrt{9}}{\\sqrt{4}} = \\dfrac{3}{2}$, car $9$ et $4$ sont des carrés parfaits.')),
    (2076, 'Espérance – Variance – Écart-type', 2, 'Un dé truqué à $4$ faces numérotées de $1$ à $4$ est tel que $P(X=1)=\\dfrac{1}{2}$, $P(X=2)=\\dfrac{1}{4}$, $P(X=3)=\\dfrac{1}{8}$, $P(X=4)=\\dfrac{1}{8}$, où $X$ est le résultat obtenu. Vérifier que cette loi est valide, puis calculer $E(X)$.', 'La loi est valide (somme $=1$) et $E(X) = \\dfrac{15}{8}$', "Vérifier d'abord que la somme des probabilités vaut $1$, puis utiliser $E(X) = \\sum x_i p_i$.", ('Étape 1 : $\\dfrac{1}{2}+\\dfrac{1}{4}+\\dfrac{1}{8}+\\dfrac{1}{8} = \\dfrac{4}{8}+\\dfrac{2}{8}+\\dfrac{1}{8}+\\dfrac{1}{8} = 1$ : la loi est valide.', 'Étape 2 : $E(X) = 1\\times\\dfrac{1}{2} + 2\\times\\dfrac{1}{4} + 3\\times\\dfrac{1}{8} + 4\\times\\dfrac{1}{8} = \\dfrac{15}{8}$.')),
    (2077, 'Espérance – Variance – Écart-type', 3, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=0)=\\dfrac{2}{5}$, $P(X=2)=\\dfrac{3}{10}$, $P(X=5)=\\dfrac{1}{5}$, $P(X=8)=\\dfrac{1}{10}$. Calculer $E(X)$, puis $V(X)$ et $\\sigma(X)$.", '$E(X) = \\dfrac{12}{5}$, $V(X) = \\dfrac{171}{25}$ et $\\sigma(X) = \\sqrt{\\dfrac{171}{25}}$', 'Calculer $E(X)$, puis $E(X^2)$, puis $V(X) = E(X^2)-(E(X))^2$, et enfin $\\sigma(X) = \\sqrt{V(X)}$.', ('Étape 1 : $E(X) = 0\\times\\dfrac{2}{5} + 2\\times\\dfrac{3}{10} + 5\\times\\dfrac{1}{5} + 8\\times\\dfrac{1}{10} = \\dfrac{12}{5}$.', 'Étape 2 : $E(X^2) = 0\\times\\dfrac{2}{5} + 4\\times\\dfrac{3}{10} + 25\\times\\dfrac{1}{5} + 64\\times\\dfrac{1}{10} = \\dfrac{63}{5}$.', 'Étape 3 : $V(X) = E(X^2)-(E(X))^2 = \\dfrac{63}{5} - (\\dfrac{12}{5})^2 = \\dfrac{171}{25}$.', 'Étape 4 : $\\sigma(X) = \\sqrt{V(X)} = \\sqrt{\\dfrac{171}{25}}$.')),
    (2078, 'Espérance – Variance – Écart-type', 3, 'Un jeu consiste à miser $3$ euros. Avec une probabilité $\\dfrac{3}{5}$, le joueur perd sa mise (gain $X=-3$) ; avec une probabilité $\\dfrac{2}{5}$, il remporte $10$ euros (gain $X=10$). Calculer $E(X)$ et interpréter ce résultat pour un joueur qui jouerait un très grand nombre de parties.', '$E(X) = \\dfrac{11}{5}$ : en moyenne, sur un grand nombre de parties, le joueur gagne environ 2.20 euros par partie ; le jeu lui est favorable.', '$E(X)$ représente le gain moyen par partie sur un très grand nombre de répétitions.', ('Étape 1 : $E(X) = -3\\times\\dfrac{3}{5} + 10\\times\\dfrac{2}{5} = \\dfrac{11}{5}$.', 'Étape 2 : Comme $E(X) = \\dfrac{11}{5} > 0$, le jeu est favorable au joueur : en moyenne, sur un grand nombre de parties, il gagnera environ 2.20 euros par partie jouée.')),
    (2079, 'Espérance – Variance – Écart-type', 2, "Deux capteurs de température donnent des mesures dont les écarts par rapport à la valeur réelle suivent des lois d'espérance nulle, avec $\\sigma(X_1) = 0,2$ pour le capteur $1$ et $\\sigma(X_2) = 1,5$ pour le capteur $2$. Sans calcul supplémentaire, expliquer ce que ces valeurs indiquent sur la fiabilité des deux capteurs.", 'Le capteur $1$ est plus fiable : son écart-type, bien plus petit, indique que ses mesures sont beaucoup moins dispersées autour de la valeur réelle.', "L'écart-type mesure la dispersion des valeurs autour de la moyenne : plus il est petit, plus les mesures sont regroupées autour de la valeur attendue.", ("Étape 1 : L'écart-type mesure la dispersion (la variabilité) des valeurs d'une variable aléatoire autour de son espérance.", 'Étape 2 : Comme $\\sigma(X_1) = 0,2 \\ll \\sigma(X_2) = 1,5$, les mesures du capteur $1$ sont beaucoup plus regroupées autour de la valeur réelle (espérance nulle) que celles du capteur $2$.', 'Étape 3 : Le capteur $1$ est donc plus précis et plus fiable ; le capteur $2$ produit des mesures beaucoup plus dispersées, donc moins prévisibles.')),
    (2080, 'Espérance – Variance – Écart-type', 2, "Un jeu de pile ou face équilibré rapporte $5$ euros si le joueur obtient pile, et lui fait perdre $5$ euros s'il obtient face. Le jeu est-il équitable (c'est-à-dire d'espérance nulle) ? Justifier en calculant $E(X)$, où $X$ est le gain algébrique du joueur.", 'Oui, le jeu est équitable car $E(X) = 0$.', 'Un jeu est équitable si et seulement si $E(X) = 0$ : calculer $E(X)$ à partir de la loi de $X$.', ('Étape 1 : $P(X=5) = \\dfrac{1}{2}$ et $P(X=-5) = \\dfrac{1}{2}$.', 'Étape 2 : $E(X) = 5\\times\\dfrac{1}{2} + (-5)\\times\\dfrac{1}{2} = 0$.', "Étape 3 : Comme $E(X) = 0$, le jeu est équitable : en moyenne, sur un grand nombre de parties, le joueur ne gagne ni ne perd d'argent.")),
    (2081, 'Espérance – Variance – Écart-type', 4, "Un jeu propose de gagner $20$ euros avec une probabilité $\\dfrac{1}{5}$, et de perdre une mise $m$ (en euros) avec une probabilité $\\dfrac{4}{5}$. Déterminer la valeur de $m$ qui rend ce jeu équitable (c'est-à-dire $E(X) = 0$, où $X$ est le gain algébrique).", '$m = 5$ euros', "Poser $E(X) = 20\\times\\dfrac{1}{5} - m\\times\\dfrac{4}{5}$ et résoudre l'équation $E(X)=0$.", ('Étape 1 : $E(X) = 20\\times\\dfrac{1}{5} + (-m)\\times\\dfrac{4}{5} = 4 - \\dfrac{4m}{5}$.', 'Étape 2 : Un jeu équitable vérifie $E(X) = 0$, donc $4 - \\dfrac{4m}{5} = 0$, soit $\\dfrac{4m}{5} = 4$.', 'Étape 3 : $m = 4\\times\\dfrac{5}{4} = 5$. Une mise de $5$ euros rend donc ce jeu équitable.')),
    (2082, 'Espérance – Variance – Écart-type', 2, 'Un élève affirme avoir trouvé $V(X) = -\\dfrac{3}{4}$ pour une variable aléatoire $X$. Vrai ou faux : « ce résultat est possible ». Justifier.', 'Faux : une variance est toujours positive ou nulle, car $V(X) = E\\left[(X-E(X))^2\\right]$ est une moyenne de carrés.', 'La variance est une moyenne pondérée de quantités au carré $(x_i - E(X))^2$, donc toujours $\\geqslant 0$.', ('Étape 1 : La variance se définit comme $V(X) = E\\left[(X-E(X))^2\\right] = \\displaystyle\\sum_i (x_i-E(X))^2\\, p_i$.', 'Étape 2 : Chaque terme $(x_i-E(X))^2$ est un carré, donc positif ou nul, et chaque $p_i$ est positif ou nul : la somme est donc toujours positive ou nulle.', "Étape 3 : Un résultat négatif comme $-\\dfrac{3}{4}$ est donc impossible : l'élève a nécessairement commis une erreur de calcul. L'affirmation est fausse.")),
    (2083, 'Espérance – Variance – Écart-type', 1, 'Une variable aléatoire $X$ prend les valeurs $0$ et $10$, avec $P(X=0)=\\dfrac{1}{2}$ et $P(X=10)=\\dfrac{1}{2}$. Un élève affirme : « $E(X)$ doit forcément être égale à $0$ ou à $10$, puisque ce sont les deux seules valeurs possibles de $X$. » Vrai ou faux ? Calculer $E(X)$ pour justifier.', "Faux : $E(X) = 5$, qui n'est ni $0$ ni $10$.", "L'espérance est une moyenne pondérée des valeurs possibles ; elle n'a pas besoin d'être elle-même une valeur prise par $X$.", ('Étape 1 : $E(X) = 0\\times\\dfrac{1}{2} + 10\\times\\dfrac{1}{2} = 5$.', "Étape 2 : $E(X) = 5$ n'est ni $0$ ni $10$ : l'espérance est une moyenne, elle peut prendre une valeur intermédiaire jamais réellement observée par $X$. L'affirmation de l'élève est fausse.")),
    (2084, 'Espérance – Variance – Écart-type', 3, "La loi de probabilité d'une variable aléatoire $X$ est donnée par $P(X=-2)=\\dfrac{1}{4}$, $P(X=3)=\\dfrac{3}{4}$. Un élève calcule : « $E(X^2) = 4\\times\\dfrac{1}{4}+9\\times\\dfrac{3}{4} = \\dfrac{31}{4}$, donc $V(X) = \\dfrac{31}{4}$ ». Identifier son erreur et donner la valeur correcte de $V(X)$.", "$V(X) = \\dfrac{75}{16}$ : l'élève a confondu $V(X)$ avec $E(X^2)$, en oubliant de soustraire $(E(X))^2$.", 'La formule complète est $V(X) = E(X^2) - (E(X))^2$, jamais $V(X)=E(X^2)$ seul.', ("Étape 1 : L'élève a correctement calculé $E(X^2) = \\dfrac{31}{4}$, mais a oublié la seconde partie de la formule $V(X) = E(X^2)-(E(X))^2$.", "Étape 2 : Il faut d'abord calculer $E(X) = -2\\times\\dfrac{1}{4} + 3\\times\\dfrac{3}{4} = \\dfrac{7}{4}$.", 'Étape 3 : $V(X) = E(X^2) - (E(X))^2 = \\dfrac{31}{4} - (\\dfrac{7}{4})^2 = \\dfrac{75}{16}$, différent du résultat erroné $\\dfrac{31}{4}$.')),
    (2085, 'Espérance – Variance – Écart-type', 3, 'Une variable aléatoire $X$ est telle que $E(X) = \\dfrac{2}{3}$ et $V(X) = \\dfrac{5}{2}$. On pose $Y = -3X+1$. Un élève écrit : « $V(Y) = -3\\times V(X) = -3\\times\\dfrac{5}{2} = -\\dfrac{15}{2}$ ». Identifier deux erreurs dans son raisonnement et donner le calcul correct de $V(Y)$.', '$V(Y) = \\dfrac{45}{2}$ : la formule correcte est $V(aX+b) = a^2 V(X)$ (avec le carré de $a$, jamais de $b$), et une variance ne peut jamais être négative.', 'La formule est $V(aX+b) = a^2\\, V(X)$ : ne pas oublier le carré sur le coefficient $a$.', ("Étape 1 : Première erreur : l'élève utilise $V(Y) = a\\times V(X)$ au lieu de $V(Y) = a^2\\times V(X)$ (le coefficient doit être élevé au carré).", "Étape 2 : Seconde erreur, conséquence de la première : il obtient une variance négative, ce qui est impossible par définition (une variance est toujours $\\geqslant 0$), ce qui aurait dû l'alerter.", 'Étape 3 : Le calcul correct est $V(Y) = (-3)^2\\times\\dfrac{5}{2} = 9\\times\\dfrac{5}{2} = \\dfrac{45}{2}$.')),
    (2086, 'Espérance – Variance – Écart-type', 4, "Une compagnie d'assurance propose un contrat à $100$ euros par an. En cas de sinistre (probabilité $\\dfrac{1}{40}$), elle verse une indemnité de $2000$ euros à l'assuré. On note $X$ le gain algébrique de la compagnie sur ce contrat (prime encaissée moins indemnité éventuellement versée). Calculer $E(X)$ et interpréter ce résultat pour la compagnie.", '$E(X) = 50$ : en moyenne, sur un grand nombre de contrats identiques, la compagnie gagne 50.0 euros par contrat.', "$X$ vaut $100$ s'il n'y a pas de sinistre (probabilité $1-\\dfrac{1}{40}$), et $100-2000=-1900$ en cas de sinistre (probabilité $\\dfrac{1}{40}$).", ('Étape 1 : $X = 100$ euros avec probabilité $\\dfrac{39}{40}$ (pas de sinistre), et $X = 100-2000=-1900$ euros avec probabilité $\\dfrac{1}{40}$ (sinistre).', 'Étape 2 : $E(X) = 100\\times\\dfrac{39}{40} + (-1900)\\times\\dfrac{1}{40} = 50$.', 'Étape 3 : Comme $E(X) = 50 > 0$, la compagnie réalise en moyenne un bénéfice de 50.0 euros par contrat de ce type, sur un grand nombre de contrats.')),
    (2087, 'Espérance – Variance – Écart-type', 3, 'Un investisseur place $2000$ euros dans un projet. Avec une probabilité $\\dfrac{3}{10}$, il perd $1000$ euros ; avec une probabilité $\\dfrac{7}{10}$, il gagne $500$ euros. On note $X$ le gain algébrique. Calculer $E(X)$ et expliquer si cet investissement est intéressant en moyenne.', "$E(X) = 50$ : l'investissement est favorable en moyenne, car $E(X) > 0$.", 'Calculer $E(X) = \\sum x_i p_i$, puis comparer le résultat à $0$.', ('Étape 1 : $E(X) = -1000\\times\\dfrac{3}{10} + 500\\times\\dfrac{7}{10} = 50$.', "Étape 2 : Comme $E(X) = 50 > 0$, l'investissement est favorable en moyenne sur un grand nombre de répétitions, même s'il comporte un risque réel de perte (probabilité $\\dfrac310$) sur un placement unique.")),
    (2088, 'Espérance – Variance – Écart-type', 4, 'Deux jeux $A$ et $B$ sont proposés. Jeu $A$ : gain $X$ avec $P(X=-1)=\\dfrac{1}{2}$, $P(X=1)=\\dfrac{1}{2}$. Jeu $B$ : gain $Y$ avec $P(Y=-10)=\\dfrac{1}{2}$, $P(Y=10)=\\dfrac{1}{2}$. Comparer $E(X)$ à $E(Y)$, puis $V(X)$ à $V(Y)$, et conclure sur la différence entre les deux jeux malgré leur point commun.', '$E(X) = E(Y) = 0$ (les deux jeux sont équitables), mais $V(X) = 1 \\neq V(Y) = 100$ : le jeu $B$ est bien plus risqué.', 'Deux jeux peuvent avoir la même espérance mais des variances très différentes : la variance mesure le risque, pas la rentabilité moyenne.', ('Étape 1 : $E(X) = -1\\times\\dfrac{1}{2}+1\\times\\dfrac{1}{2} = 0$ et $E(Y) = -10\\times\\dfrac{1}{2}+10\\times\\dfrac{1}{2} = 0$ : les deux jeux sont équitables.', 'Étape 2 : $V(X) = 1\\times\\dfrac{1}{2}+1\\times\\dfrac{1}{2} - 0^2 = 1$ et $V(Y) = 100\\times\\dfrac{1}{2}+100\\times\\dfrac{1}{2} - 0^2 = 100$.', 'Étape 3 : Bien que $E(X)=E(Y)=0$, on a $V(Y) \\gg V(X)$ : le jeu $B$ présente des gains ou pertes bien plus importants en valeur absolue, il est donc beaucoup plus risqué que le jeu $A$, à espérance égale.')),
    (2089, 'Espérance – Variance – Écart-type', 5, 'Deux placements sont proposés. Placement $C$ : gain $\\dfrac{4}{5}$ de chances de $200$ euros, $\\dfrac{1}{5}$ de chances de perdre $300$ euros. Placement $D$ : gain de $100$ euros ou $50$ euros, chacun avec probabilité $\\dfrac{1}{2}$. Calculer $E(C)$ et $E(D)$, puis $V(C)$ et $V(D)$, et déterminer lequel des deux placements est à la fois le plus rentable en moyenne et le plus risqué.', '$E(C) = 100$ et $E(D) = 75$ : $C$ est plus rentable en moyenne. $V(C) = 40000$ et $V(D) = 625$ : $C$ est aussi le plus risqué.', 'Calculer séparément $E$ et $V$ pour chaque placement, puis comparer les deux paires de résultats.', ('Étape 1 : $E(C) = 200\\times\\dfrac{4}{5} + (-300)\\times\\dfrac{1}{5} = 100$.', 'Étape 2 : $E(D) = 100\\times\\dfrac{1}{2} + 50\\times\\dfrac{1}{2} = 75$.', 'Étape 3 : $V(C) = 200^2\\times\\dfrac{4}{5} + (-300)^2\\times\\dfrac{1}{5} - (100)^2 = 40000$, et $V(D) = 100^2\\times\\dfrac{1}{2}+50^2\\times\\dfrac{1}{2} - (75)^2 = 625$.', 'Étape 4 : $E(C) = 100 > E(D) = 75$ et $V(C) = 40000 > V(D) = 625$ : le placement $C$ est donc à la fois plus rentable en moyenne et plus risqué que le placement $D$.')),
    (2090, 'Espérance – Variance – Écart-type', 5, "Une loterie vend $500$ billets à $4$ euros. Il y a $1$ billet gagnant $200$ euros, $10$ billets gagnants $20$ euros chacun, et le reste ne rapporte rien. On note $X$ le gain net (somme gagnée moins prix du billet) d'un joueur achetant $1$ billet. 1) Déterminer la loi de $X$. 2) Calculer $E(X)$. 3) Un joueur achète $10$ billets indépendants ; en admettant que son gain net total $Y$ vérifie $Y=10X$ en espérance et en variance (approximation usuelle pour des tirages indépendants et identiques), calculer $E(Y)$ et $V(Y)$ à l'aide des formules de linéarité.", '$E(X) = -\\dfrac{16}{5}$, $V(X) = \\dfrac{2184}{25}$ ; $E(Y) = -32$ et $V(Y) = 8736$.', 'Construire la loi de $X$ à partir des effectifs, calculer $E(X)$ et $V(X)$, puis utiliser $E(aX)=aE(X)$ et $V(aX)=a^2V(X)$.', ('Étape 1 : $X=196$ (billet à $200$€) avec probabilité $\\dfrac{1}{500}$, $X=16$ (billet à $20$€) avec probabilité $\\dfrac{10}{500}=\\dfrac{1}{50}$, $X=-4$ (billet perdant) avec probabilité $\\dfrac{489}{500}$.', 'Étape 2 : $E(X) = 196\\times\\dfrac{1}{500} + 16\\times\\dfrac{10}{500} + (-4)\\times\\dfrac{489}{500} = -\\dfrac{16}{5}$.', 'Étape 3 : On calcule $V(X) = \\dfrac{2184}{25}$ (par la formule $V(X)=E(X^2)-(E(X))^2$).', 'Étape 4 : Pour $Y=10X$, on utilise $E(Y) = 10\\times E(X) = 10\\times -\\dfrac{16}{5} = -32$ et $V(Y) = 10^2\\times V(X) = 100\\times \\dfrac{2184}{25} = 8736$.')),
    (2091, 'Espérance – Variance – Écart-type', 5, "Un jeu rapporte $X$ euros à un joueur : $P(X=-2)=\\dfrac{3}{5}$ (le joueur perd $2$ euros), $P(X=8)=\\dfrac{2}{5}$ (le joueur gagne $8$ euros). 1) Calculer $E(X)$ et dire si le jeu est favorable au joueur, à l'organisateur, ou équitable. 2) On souhaite modifier le jeu en ajoutant un montant fixe $c$ au gain (nouveau gain $Y=X+c$) pour le rendre équitable. Déterminer la valeur de $c$ à l'aide de la formule $E(Y)=E(X)+c$.", "$E(X) = 2$ : le jeu est favorable au joueur (défavorable à l'organisateur). Il faut $c = -2$ pour rendre le jeu équitable.", 'Utiliser $E(X)=\\sum x_i p_i$, comparer à $0$, puis résoudre $E(X)+c=0$.', ('Étape 1 : $E(X) = -2\\times\\dfrac{3}{5} + 8\\times\\dfrac{2}{5} = 2$.', "Étape 2 : Comme $E(X) = 2 > 0$, le jeu est en réalité favorable au joueur (et donc défavorable à l'organisateur) en moyenne.", 'Étape 3 : Pour rendre le jeu équitable, on cherche $c$ tel que $E(Y) = E(X)+c = 0$, donc $c = -E(X) = -2$.', 'Étape 4 : Il faudrait donc retirer $2.00$ euros au gain (par exemple en augmentant la mise) pour que le jeu devienne équitable.')),
)
